import { Box, Heading, Separator, Text } from "@chakra-ui/react";
import type { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import { Brain, Icon, Sliders, Wrench } from "../Icon";
import { ScrollContainer, ScrollContent } from "../VerticalScroll";
import { Tooltip } from "../Tooltip";
import { useInspectorStore } from "../store";
import { selectSkillMemory } from "../store/selectors";
import type { MemorySource } from "../types";
import { deriveSkillMemoryView, type MemorySectionView } from "./deriveSkillMemoryView";

// Same icon vocabulary as the conversation log: wrench = tool execution,
// brain = the LLM, sliders = the engine itself.
const SOURCE_CONFIG: Record<MemorySource, { icon: IconDefinition; label: string }> = {
  tool: { icon: Wrench, label: "Last set by a tool" },
  llm: { icon: Brain, label: "Last set by the LLM" },
  system: { icon: Sliders, label: "Last set by the engine" },
};

function SourceBadge({ source }: { readonly source: MemorySource }) {
  const { icon, label } = SOURCE_CONFIG[source];
  return (
    <Tooltip content={label}>
      <Box
        as="span"
        color="fg.muted"
        flexShrink={0}
        data-testid="memory-source"
        data-source={source}
      >
        <Icon icon={icon} size="sm" />
      </Box>
    </Tooltip>
  );
}

// The section heading and row spacing mirror the v1 memory pane
// (MemoryDetails.tsx) so the two panes align visually. Each value lives in
// exactly one place; the row/heading components below are the only consumers.
function MemorySectionContainer({
  testId,
  heading,
  children,
}: {
  readonly testId: string;
  readonly heading: string;
  readonly children: React.ReactNode;
}) {
  return (
    <Box display="flex" flexDirection="column" data-testid={testId}>
      <Heading textStyle="sm" px="2" py="1" mb="1">
        {heading}
      </Heading>
      {children}
    </Box>
  );
}

function MemoryValueRow({
  name,
  value,
  title,
  source,
  testId,
}: {
  readonly name: string;
  readonly value: unknown;
  readonly title: string;
  readonly source: MemorySource | null;
  readonly testId?: string;
}) {
  const isUnset = value === null || value === undefined;
  const valueStr = isUnset ? "–" : JSON.stringify(value);
  return (
    <Box data-testid="memory-entry">
      <Box
        display="flex"
        alignItems="center"
        gap="2"
        px="2"
        py="1"
        borderRadius="lg"
        color="fg"
        data-testid={testId}
      >
        <Box display="flex" alignItems="center" gap="1.5" width="50%" minWidth={0}>
          <Text variant="primary" textStyle="sm" truncate title={title}>
            {name}
          </Text>
          {source ? <SourceBadge source={source} /> : null}
        </Box>
        <Text
          variant="primary"
          textStyle="sm"
          fontFamily="mono"
          width="50%"
          truncate
          color={isUnset ? "fg.muted" : "fg"}
          title={valueStr}
          data-testid="slot-value"
        >
          {valueStr}
        </Text>
      </Box>
    </Box>
  );
}

function MemorySectionBlock({ section }: { readonly section: MemorySectionView }) {
  return (
    <MemorySectionContainer testId={`${section.title}-section`} heading={section.title}>
      {section.rows.map((row) => (
        <MemoryValueRow
          key={row.fullName}
          name={row.name}
          value={row.value}
          title={row.description ? `${row.fullName} — ${row.description}` : row.fullName}
          source={row.source}
          testId={`slot-${row.fullName}`}
        />
      ))}
    </MemorySectionContainer>
  );
}

/**
 * Memory pane for skill-based (Mantle) projects: every skill's memory in its
 * own section (with per-entry write provenance), plus the LLM's
 * discovered-facts scratchpad and the shared project / system scopes.
 * Sections and rows are ordered newest-written first; declared-but-unset
 * entries sit at the bottom of their section.
 */
export const SkillMemoryDetails = () => {
  const memory = useInspectorStore(selectSkillMemory);
  const skillCatalog = useInspectorStore((state) => state.skillCatalog);
  const slotRelatedEvents = useInspectorStore((state) => state.slotRelatedEvents);
  const view = deriveSkillMemoryView(memory ?? {}, skillCatalog, slotRelatedEvents);

  return (
    <Box bg="white" borderRadius="lg">
      <ScrollContainer>
        <ScrollContent
          withSpacing={false}
          pl="4"
          pr="7"
          py="2"
          css={{ "& [data-orientation='vertical']": { display: "none" } }}
        >
          <Box display="flex" flexDirection="column" gap="4">
            {view.sections.map((section, index) => (
              <Box key={section.title}>
                {index > 0 && <Separator mb="4" mx="-4" />}
                <MemorySectionBlock section={section} />
              </Box>
            ))}
          </Box>
        </ScrollContent>
      </ScrollContainer>
    </Box>
  );
};
